<script setup>import CustomerNavigation from '@/Components/Customer/CustomerNavigation.vue';import InputError from '@/Components/InputError.vue';import PortalLayout from '@/Layouts/PortalLayout.vue';import{Head,useForm}from'@inertiajs/vue3';const props=defineProps({ticket:Object});const form=useForm({body:'',attachments:[]});const submit=()=>form.post(route('support.messages.store',props.ticket.uuid),{forceFormData:true,onSuccess:()=>form.reset()});</script>
<template><Head :title="ticket.ticket_number"/><PortalLayout area="Customer Portal"><template #navigation><CustomerNavigation active="support"/></template><div v-if="$page.props.flash.success" class="success-message mb-4">{{ $page.props.flash.success }}</div><div class="mb-6"><p class="text-sm font-bold text-cyan-700">{{ ticket.ticket_number }}</p><h1 class="text-3xl font-bold">{{ ticket.subject }}</h1><p class="mt-2 text-slate-500">{{ ticket.product?.name || 'General' }} · {{ ticket.category }} · {{ ticket.priority }} · {{ ticket.status }}</p></div><div class="space-y-4"><article v-for="message in ticket.messages" :key="message.uuid" class="rounded-2xl bg-white p-6 shadow-sm"><div class="flex justify-between"><strong>{{ message.sender.name }}</strong><time class="text-sm text-slate-500">{{ message.created_at }}</time></div><p class="mt-3 whitespace-pre-line">{{ message.body }}</p><div class="mt-3 flex gap-3"><a v-for="file in message.attachments" :key="file.uuid" :href="route('support.attachments.show',file.uuid)" class="text-sm font-bold text-cyan-700">{{ file.original_name }}</a></div></article></div><form v-if="ticket.status!=='closed'" class="form-card mt-6" @submit.prevent="submit"><label>Reply<textarea v-model="form.body" rows="5" required/><InputError :message="form.errors.body"/></label><label>Attachments<input type="file" multiple @change="form.attachments=Array.from($event.target.files)"/></label><button class="form-button" :disabled="form.processing">Send reply</button></form><p v-else class="mt-6 rounded-xl bg-slate-200 p-4">This ticket is closed. Contact support if it needs to be reopened.</p></PortalLayout></template>
